class ReportMailer:
    def __init__(self, mailer: EmailClient) -> None:
        self._mailer = mailer

    def send_summary(self, count: int, address: str) -> dict[str, str]:
        return self._mailer.send(address, f"{count} orders")

class ReportView:
    def __init__(self, repository: OrderRepository, mailer: EmailClient) -> None:
